/* Original implementation of the single-interaction, scalar/paraxial
 * weakly-local Gaussian-mode estimator. See method.html for derivation.
 * Lengths in millimetres. No code from wave_tracer is incorporated. */
export const NODES=[-0.9894009349916499,-0.9445750230732326,-0.8656312023878318,-0.755404408355003,-0.6178762444026438,-0.4580167776572274,-0.2816035507792589,-0.09501250983763744,0.09501250983763744,0.2816035507792589,0.4580167776572274,0.6178762444026438,0.755404408355003,0.8656312023878318,0.9445750230732326,0.9894009349916499];
export const WEIGHTS=[0.0271524594117541,0.0622535239386479,0.0951585116824928,0.1246289712555339,0.1495959888165767,0.1691565193950025,0.1826034150449236,0.1894506104550685,0.1894506104550685,0.1826034150449236,0.1691565193950025,0.1495959888165767,0.1246289712555339,0.0951585116824928,0.0622535239386479,0.0271524594117541];
export const MODEL={sigma0:0.035,sourceSigma:0.7,height:0.18,tail:5,spanX:24,spanY:15};
export function parameters(s){const wavelength=s.lambda*1e-6,L=s.screenDistance*1000,k=2*Math.PI/wavelength,rho=L/k,S=2*MODEL.sigma0**2,D=S*S+rho*rho;return {...MODEL,wavelength,L,k,rho,S,D,sigmaL:Math.sqrt(D/(2*S)),width:s.slitWidth,separation:s.separation};}
export function integral(a,b,X,xi,p,tail=p.tail){const c=-p.sigmaL*xi; a=Math.max(a,c-tail*p.sigmaL);b=Math.min(b,c+tail*p.sigmaL);if(b<=a)return [0,0];const h=(b-a)/2,m=(a+b)/2;let re=0,im=0;const beta=p.rho/(2*p.D),gamma=-p.k*X/p.L-xi*p.sigmaL*p.S*p.S/(p.rho*p.D);for(let n=0;n<16;n++){const t=m+h*NODES[n],amp=Math.exp(-t*t/(4*p.sourceSigma**2)-t*t/(4*p.sigmaL**2)-xi*t/(2*p.sigmaL)),phase=beta*t*t+gamma*t;re+=WEIGHTS[n]*amp*Math.cos(phase);im+=WEIGHTS[n]*amp*Math.sin(phase);}return [h*re,h*im];}
export function coneHits(x0,x1,y0,y1,xi,eta,p,tail=p.tail){const cx=-p.sigmaL*xi,cy=-p.sigmaL*eta;const axis=Math.SQRT2*tail*(p.sigma0+p.L/(2*p.k*p.sigma0));const rx=Math.max(x0,Math.min(x1,cx)),ry=Math.max(y0,Math.min(y1,cy));return ((rx-cx)**2+(ry-cy)**2)/(axis*axis)<=1;}
export function waveSample(X,Y,xi,eta,p,tail=p.tail){const left=coneHits(-p.separation/2-p.width/2,-p.separation/2+p.width/2,-p.height/2,p.height/2,xi,eta,p,tail),right=coneHits(p.separation/2-p.width/2,p.separation/2+p.width/2,-p.height/2,p.height/2,xi,eta,p,tail); const a=left?integral(-p.separation/2-p.width/2,-p.separation/2+p.width/2,X,xi,p,tail):[0,0],b=right?integral(p.separation/2-p.width/2,p.separation/2+p.width/2,X,xi,p,tail):[0,0],y=integral(-p.height/2,p.height/2,Y,eta,p,tail);return ((a[0]+b[0])**2+(a[1]+b[1])**2)*(y[0]**2+y[1]**2)/(p.wavelength*p.L)**2;}
function filtered(a,b,X,p){const h=(b-a)/2,m=(a+b)/2;let v=0;for(let n=0;n<16;n++){const t=m+h*NODES[n];v+=WEIGHTS[n]*Math.exp(-t*t/(2*p.sourceSigma**2)-(t-X)**2/(2*p.sigma0**2));}return v*h/(Math.sqrt(2*Math.PI)*p.sigma0);}
export function geometric(X,Y,p){return (filtered(-p.separation/2-p.width/2,-p.separation/2+p.width/2,X,p)+filtered(p.separation/2-p.width/2,p.separation/2+p.width/2,X,p))*filtered(-p.height/2,p.height/2,Y,p);}
export function normalPair(a,b){const r=Math.sqrt(-2*Math.log(Math.max(a,1e-8))),t=2*Math.PI*b;return [r*Math.cos(t),r*Math.sin(t)];}
export function hash(v){v=Math.imul(v^(v>>>16),0x7feb352d);v=Math.imul(v^(v>>>15),0x846ca68b);return (v^(v>>>16))>>>0;}
export function normals(pixel,sample){const seed=hash((pixel+Math.imul(sample+1,747796405))>>>0);return normalPair((hash(seed)+.5)/4294967296,(hash(seed^0x68bc21eb)+.5)/4294967296);}
export function fresnel(X,Y,p){const saved={...p,sigmaL:1e20,S:0,D:p.rho*p.rho};return waveSample(X,Y,0,0,saved,1e6);}
